import{az as l,P as e,Q as t,aQ as o}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const g=JSON.parse('{"title":"页面加载速度优化","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/优化/页面加载速度优化.md","filePath":"面试题/优化/页面加载速度优化.md","lastUpdated":1782637463000}'),r={name:"面试题/优化/页面加载速度优化.md"};function s(n,a,i,d,c,h){return e(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="页面加载速度优化" tabindex="-1">页面加载速度优化 <a class="header-anchor" href="#页面加载速度优化" aria-label="Permalink to “页面加载速度优化”">​</a></h1><p>页面加载优化围绕一条主线：<strong>减少资源体积 → 减少请求次数 → 缩短关键路径 → 降低渲染与执行开销 → 提升用户感知</strong>。面试中建议先说指标，再按链路分层展开。</p><hr><h2 id="性能指标体系" tabindex="-1">性能指标体系 <a class="header-anchor" href="#性能指标体系" aria-label="Permalink to “性能指标体系”">​</a></h2><h3 id="core-web-vitals-核心指标" tabindex="-1">Core Web Vitals（核心指标） <a class="header-anchor" href="#core-web-vitals-核心指标" aria-label="Permalink to “Core Web Vitals（核心指标）”">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>优秀标准</th></tr></thead><tbody><tr><td><strong>LCP</strong></td><td>最大内容绘制，衡量首屏主要内容出现速度</td><td>&lt; 2.5s</td></tr><tr><td><strong>INP</strong></td><td>交互到下一次绘制，衡量页面响应性（替代 FID）</td><td>&lt; 200ms</td></tr><tr><td><strong>CLS</strong></td><td>累积布局偏移，衡量视觉稳定性</td><td>&lt; 0.1</td></tr></tbody></table><h3 id="其他常用指标" tabindex="-1">其他常用指标 <a class="header-anchor" href="#其他常用指标" aria-label="Permalink to “其他常用指标”">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>优秀标准</th></tr></thead><tbody><tr><td><strong>FCP</strong></td><td>首次内容绘制</td><td>&lt; 1.8s</td></tr><tr><td><strong>TTFB</strong></td><td>首字节时间，反映服务端与网络</td><td>&lt; 0.6s</td></tr><tr><td><strong>TTI</strong></td><td>可交互时间</td><td>&lt; 3.8s</td></tr><tr><td><strong>DOMContentLoaded</strong></td><td>HTML 解析完成</td><td>视业务而定</td></tr><tr><td><strong>load</strong></td><td>页面及资源全部加载完成</td><td>视业务而定</td></tr></tbody></table><h3 id="浏览器加载阶段-简要" tabindex="-1">浏览器加载阶段（简要） <a class="header-anchor" href="#浏览器加载阶段-简要" aria-label="Permalink to “浏览器加载阶段（简要）”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>DNS 解析 → TCP 连接 → TLS 握手 → 请求 HTML → 解析 DOM</span></span>
<span class="line"><span>→ 加载 CSS/JS → 构建 CSSOM → 执行 JS → 构建渲染树 → 布局 → 绘制 → 合成</span></span></code></pre></div><p><strong>关键路径</strong>：HTML、CSS、阻塞 JS 会直接影响首屏；图片、字体、异步资源通常不阻塞 DOM 解析（CSS 会阻塞渲染）。</p><hr><h2 id="_1-网络层面" tabindex="-1">1. 网络层面 <a class="header-anchor" href="#_1-网络层面" aria-label="Permalink to “1. 网络层面”">​</a></h2><h3 id="_1-1-资源压缩" tabindex="-1">1.1 资源压缩 <a class="header-anchor" href="#_1-1-资源压缩" aria-label="Permalink to “1.1 资源压缩”">​</a></h3><ul><li><strong>代码压缩</strong>：JS / CSS / HTML 压缩，生产环境移除 <code>console</code>、<code>debugger</code></li><li><strong>Tree-shaking</strong>：剔除未使用的导出，需配合 <code>sideEffects</code> 配置</li><li><strong>图片优化</strong>： <ul><li>大图：压缩后放 CDN，优先 WebP / AVIF</li><li>小图（icon）：可 inline 为 base64 或 SVG，<strong>避免大量小文件请求</strong></li><li>响应式图片：<code>srcset</code> + <code>sizes</code>，按需加载不同尺寸</li></ul></li><li><strong>传输压缩</strong>：开启 Gzip / Brotli（Brotli 压缩率更高）</li></ul><h3 id="_1-2-请求优化" tabindex="-1">1.2 请求优化 <a class="header-anchor" href="#_1-2-请求优化" aria-label="Permalink to “1.2 请求优化”">​</a></h3><ul><li><strong>接口合并</strong>：Dashboard 类页面合并多个接口为一次请求</li><li><strong>HTTP/2 / HTTP/3</strong>：多路复用，减少连接开销</li><li><strong>域名收敛</strong>：减少 DNS 查询与 TCP 连接数（HTTP/2 下不必过度域名拆分）</li><li><strong>减少重定向</strong>：每次 301/302 都会增加 RTT</li></ul><h3 id="_1-3-懒加载" tabindex="-1">1.3 懒加载 <a class="header-anchor" href="#_1-3-懒加载" aria-label="Permalink to “1.3 懒加载”">​</a></h3><ul><li><strong>路由懒加载</strong>：<code>() =&gt; import(&#39;./Page.vue&#39;)</code></li><li><strong>组件懒加载</strong>：<code>defineAsyncComponent</code>、动态 import</li><li><strong>图片 / 视频懒加载</strong>：<code>loading=&quot;lazy&quot;</code> 或 <code>IntersectionObserver</code></li><li><strong>原则</strong>：首屏关键资源立即加载，非首屏资源延后</li></ul><h3 id="_1-4-cdn-与缓存" tabindex="-1">1.4 CDN 与缓存 <a class="header-anchor" href="#_1-4-cdn-与缓存" aria-label="Permalink to “1.4 CDN 与缓存”">​</a></h3><ul><li>静态资源（JS / CSS / 图片 / 字体）走 CDN，就近访问</li><li>配置合理的 <code>Cache-Control</code>、<code>ETag</code>，文件名带 hash 实现长期缓存</li><li>API 数据按业务设置缓存策略，避免频繁重复请求</li></ul><hr><h2 id="_2-构建与打包" tabindex="-1">2. 构建与打包 <a class="header-anchor" href="#_2-构建与打包" aria-label="Permalink to “2. 构建与打包”">​</a></h2><h3 id="_2-1-代码分割" tabindex="-1">2.1 代码分割 <a class="header-anchor" href="#_2-1-代码分割" aria-label="Permalink to “2.1 代码分割”">​</a></h3><ul><li><strong>路由级分割</strong>：按页面拆分 chunk，首屏只加载当前路由</li><li><strong>组件级分割</strong>：大组件、弹窗、图表库按需加载</li><li><strong>第三方库分割</strong>：<code>splitChunks</code> / Rollup <code>manualChunks</code>，避免 vendor 过大</li></ul><h3 id="_2-2-依赖优化" tabindex="-1">2.2 依赖优化 <a class="header-anchor" href="#_2-2-依赖优化" aria-label="Permalink to “2.2 依赖优化”">​</a></h3><ul><li>剔除无用第三方库，审计 <code>package.json</code> 体积（如 <code>webpack-bundle-analyzer</code>）</li><li>按需引入：如 <code>lodash-es</code> 替代全量 <code>lodash</code>，UI 库按需导入</li><li>大体积库与主包分离，必要时 CDN 外链（需权衡缓存与版本管理）</li><li>锁定依赖版本，避免重复打包同一库的多版本</li></ul><h3 id="_2-3-构建产物优化" tabindex="-1">2.3 构建产物优化 <a class="header-anchor" href="#_2-3-构建产物优化" aria-label="Permalink to “2.3 构建产物优化”">​</a></h3><ul><li>开启 minify、tree-shaking、压缩 CSS</li><li>小资源内联阈值：过小文件合并或 inline，减少 HTTP 请求</li><li>生产环境关闭 source map 或使用 hidden source map</li></ul><hr><h2 id="_3-页面渲染" tabindex="-1">3. 页面渲染 <a class="header-anchor" href="#_3-页面渲染" aria-label="Permalink to “3. 页面渲染”">​</a></h2><h3 id="_3-1-减少-dom-开销" tabindex="-1">3.1 减少 DOM 开销 <a class="header-anchor" href="#_3-1-减少-dom-开销" aria-label="Permalink to “3.1 减少 DOM 开销”">​</a></h3><ul><li>减少冗余标签，避免无意义嵌套</li><li>控制 DOM 节点数量，复杂页面考虑虚拟列表</li><li>避免在 JS 中频繁创建/销毁大量节点</li></ul><h3 id="_3-2-避免回流与重绘" tabindex="-1">3.2 避免回流与重绘 <a class="header-anchor" href="#_3-2-避免回流与重绘" aria-label="Permalink to “3.2 避免回流与重绘”">​</a></h3><ul><li><strong>回流（Reflow）</strong>：布局变化，开销大；<strong>重绘（Repaint）</strong>：外观变化，开销相对小</li><li>批量修改 DOM：使用 <code>DocumentFragment</code> 或离线 DOM</li><li>统一读写布局：避免「读 offset → 写 style → 再读 offset」的交替操作</li><li>动画优先使用 <code>transform</code>、<code>opacity</code>（触发合成层，不走布局）</li><li>对频繁变化的元素使用 <code>will-change</code>（适度使用，勿滥用）</li></ul><h3 id="_3-3-长列表优化" tabindex="-1">3.3 长列表优化 <a class="header-anchor" href="#_3-3-长列表优化" aria-label="Permalink to “3.3 长列表优化”">​</a></h3><ul><li><strong>虚拟滚动</strong>：只渲染可视区域 DOM，用占位高度撑开滚动条</li><li>分页加载、无限滚动按需拉取数据</li><li>避免在滚动事件中做重计算，配合节流</li></ul><h3 id="_3-4-css-优化" tabindex="-1">3.4 CSS 优化 <a class="header-anchor" href="#_3-4-css-优化" aria-label="Permalink to “3.4 CSS 优化”">​</a></h3><ul><li>精简选择器，避免深层嵌套与通配符</li><li><strong>关键 CSS 内联</strong>，非关键样式异步或延迟加载</li><li>CSS 放 <code>&lt;head&gt;</code>，避免 <code>@import</code> 阻塞</li><li>减少未使用的 CSS（PurgeCSS / UnCSS）</li></ul><hr><h2 id="_4-js-执行优化" tabindex="-1">4. JS 执行优化 <a class="header-anchor" href="#_4-js-执行优化" aria-label="Permalink to “4. JS 执行优化”">​</a></h2><h3 id="_4-1-主线程减负" tabindex="-1">4.1 主线程减负 <a class="header-anchor" href="#_4-1-主线程减负" aria-label="Permalink to “4.1 主线程减负”">​</a></h3><ul><li>拆分长任务（&gt; 50ms），避免阻塞交互与渲染</li><li>使用 <code>requestIdleCallback</code> 在浏览器空闲时执行低优先级逻辑</li><li>复杂计算、大数据处理下沉到 <strong>Web Worker</strong></li><li>防抖 / 节流控制高频事件（scroll、resize、input）</li></ul><h3 id="_4-2-脚本加载策略" tabindex="-1">4.2 脚本加载策略 <a class="header-anchor" href="#_4-2-脚本加载策略" aria-label="Permalink to “4.2 脚本加载策略”">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>行为</th><th>适用场景</th></tr></thead><tbody><tr><td>默认</td><td>阻塞 HTML 解析</td><td>关键同步脚本（尽量少用）</td></tr><tr><td><code>defer</code></td><td>HTML 解析完后按顺序执行</td><td>依赖 DOM 的非关键脚本</td></tr><tr><td><code>async</code></td><td>下载完立即执行，不保证顺序</td><td>独立脚本（统计、广告）</td></tr><tr><td><code>type=&quot;module&quot;</code></td><td>默认 defer，支持 ES Module</td><td>现代模块化脚本</td></tr></tbody></table><h3 id="_4-3-运行时优化" tabindex="-1">4.3 运行时优化 <a class="header-anchor" href="#_4-3-运行时优化" aria-label="Permalink to “4.3 运行时优化”">​</a></h3><ul><li>避免在首屏执行大量同步逻辑</li><li>延迟初始化非首屏模块（图表、地图、编辑器等）</li><li>合理使用 <code>requestAnimationFrame</code> 做动画与布局相关更新</li></ul><hr><h2 id="_5-体验优化" tabindex="-1">5. 体验优化 <a class="header-anchor" href="#_5-体验优化" aria-label="Permalink to “5. 体验优化”">​</a></h2><h3 id="_5-1-感知优化" tabindex="-1">5.1 感知优化 <a class="header-anchor" href="#_5-1-感知优化" aria-label="Permalink to “5.1 感知优化”">​</a></h3><ul><li><strong>骨架屏 / Loading / 占位图</strong>：降低等待焦虑，让用户感知「正在加载」</li><li>渐进式展示：先出框架，再填充数据</li><li>避免布局抖动：图片、广告位预留宽高（改善 CLS）</li></ul><h3 id="_5-2-资源预加载" tabindex="-1">5.2 资源预加载 <a class="header-anchor" href="#_5-2-资源预加载" aria-label="Permalink to “5.2 资源预加载”">​</a></h3><table tabindex="0"><thead><tr><th>指令</th><th>作用</th><th>典型场景</th></tr></thead><tbody><tr><td><code>preload</code></td><td>高优先级，当前页面必用</td><td>首屏字体、关键 JS/CSS</td></tr><tr><td><code>prefetch</code></td><td>低优先级，下一页面可能用</td><td>下一路由 chunk</td></tr><tr><td><code>preconnect</code></td><td>提前建立连接</td><td>第三方 API、CDN 域名</td></tr><tr><td><code>dns-prefetch</code></td><td>提前 DNS 解析</td><td>跨域资源域名</td></tr></tbody></table><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">link</span><span style="color:#C792EA;"> rel</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">preconnect</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;"> href</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">https://cdn.example.com</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">link</span><span style="color:#C792EA;"> rel</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">preload</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;"> href</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/fonts/main.woff2</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;"> as</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">font</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;"> type</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">font/woff2</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;"> crossorigin</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">link</span><span style="color:#C792EA;"> rel</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">prefetch</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;"> href</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/assets/about-chunk.js</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;"> as</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">script</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span></span></code></pre></div><h3 id="_5-3-首屏精简" tabindex="-1">5.3 首屏精简 <a class="header-anchor" href="#_5-3-首屏精简" aria-label="Permalink to “5.3 首屏精简”">​</a></h3><ul><li>优先渲染核心内容，非关键模块（评论、推荐、Footer）延后</li><li>关键数据 SSR / SSG / 流式渲染，减少白屏时间</li><li>字体：<code>font-display: swap</code> 避免 FOIT（不可见文本闪烁）</li></ul><hr><h2 id="_6-服务端与架构" tabindex="-1">6. 服务端与架构 <a class="header-anchor" href="#_6-服务端与架构" aria-label="Permalink to “6. 服务端与架构”">​</a></h2><ul><li><strong>SSR</strong>：服务端渲染 HTML，加快首屏内容到达（Vue Nuxt、React Next.js）</li><li><strong>SSG / 预渲染</strong>：静态页面直接输出 HTML，适合文档、营销页</li><li><strong>边缘缓存</strong>：HTML 片段或 API 在 CDN 边缘节点缓存</li><li><strong>接口优化</strong>：减少 payload、分页、字段裁剪、GraphQL 按需取字段</li></ul><hr><h2 id="优化检查清单" tabindex="-1">优化检查清单 <a class="header-anchor" href="#优化检查清单" aria-label="Permalink to “优化检查清单”">​</a></h2><ul><li>[ ] Core Web Vitals（LCP / INP / CLS）达标</li><li>[ ] 资源已压缩（Gzip / Brotli、minify）</li><li>[ ] 路由与组件懒加载</li><li>[ ] 图片格式、尺寸、懒加载已优化</li><li>[ ] 关键 CSS 内联，JS 非阻塞加载</li><li>[ ] 长列表使用虚拟滚动</li><li>[ ] 静态资源 CDN + 长期缓存（hash 文件名）</li><li>[ ] 长任务拆分，必要时使用 Web Worker</li><li>[ ] 骨架屏 / 占位已覆盖首屏等待</li><li>[ ] 性能监控已接入（Lighthouse、Web Vitals、RUM）</li></ul><hr><h2 id="面试高频问题" tabindex="-1">面试高频问题 <a class="header-anchor" href="#面试高频问题" aria-label="Permalink to “面试高频问题”">​</a></h2><h3 id="_1-如何衡量页面加载速度" tabindex="-1">1. 如何衡量页面加载速度？ <a class="header-anchor" href="#_1-如何衡量页面加载速度" aria-label="Permalink to “1. 如何衡量页面加载速度？”">​</a></h3><p>通过 <strong>Core Web Vitals</strong>（LCP、INP、CLS）衡量用户体验，结合 FCP、TTFB、TTI 分析瓶颈阶段。工具：Lighthouse、Chrome Performance、Web Vitals API、WebPageTest。</p><h3 id="_2-首屏-2s-如何优化到-1s" tabindex="-1">2. 首屏 2s 如何优化到 1s？ <a class="header-anchor" href="#_2-首屏-2s-如何优化到-1s" aria-label="Permalink to “2. 首屏 2s 如何优化到 1s？”">​</a></h3><ul><li>代码分割 + 路由懒加载，减小首屏 JS 体积</li><li>图片压缩、WebP、CDN 加速</li><li>关键 CSS 内联，非关键 JS 使用 <code>defer</code></li><li>SSR / 预渲染减少白屏</li><li>拆分长任务，减少主线程阻塞</li><li>接口合并、缓存、减少 TTFB</li></ul><h3 id="_3-tree-shaking-和代码分割的区别" tabindex="-1">3. Tree-shaking 和代码分割的区别？ <a class="header-anchor" href="#_3-tree-shaking-和代码分割的区别" aria-label="Permalink to “3. Tree-shaking 和代码分割的区别？”">​</a></h3><ul><li><strong>Tree-shaking</strong>：编译时删除模块内未使用的导出，减小单个文件体积</li><li><strong>代码分割</strong>：运行时按路由/组件拆成多个 chunk，按需加载</li></ul><p>两者互补：tree-shaking 让单文件更瘦，代码分割让首屏加载更少。</p><h3 id="_4-preload-和-prefetch-的区别" tabindex="-1">4. preload 和 prefetch 的区别？ <a class="header-anchor" href="#_4-preload-和-prefetch-的区别" aria-label="Permalink to “4. preload 和 prefetch 的区别？”">​</a></h3><ul><li><strong>preload</strong>：当前页面 soon 需要的资源，高优先级，会竞争带宽</li><li><strong>prefetch</strong>：未来页面可能需要的资源，低优先级，浏览器空闲时加载</li></ul><h3 id="_5-回流和重绘的区别-如何减少" tabindex="-1">5. 回流和重绘的区别？如何减少？ <a class="header-anchor" href="#_5-回流和重绘的区别-如何减少" aria-label="Permalink to “5. 回流和重绘的区别？如何减少？”">​</a></h3><ul><li><strong>回流</strong>：几何属性变化（width、height、position），需重新计算布局</li><li><strong>重绘</strong>：视觉属性变化（color、visibility），不重新布局</li></ul><p>优化：批量 DOM 操作、读写分离、动画用 <code>transform</code>/<code>opacity</code>、避免逐帧修改布局属性。</p><h3 id="_6-虚拟滚动原理" tabindex="-1">6. 虚拟滚动原理？ <a class="header-anchor" href="#_6-虚拟滚动原理" aria-label="Permalink to “6. 虚拟滚动原理？”">​</a></h3><p>根据 <code>scrollTop</code> 和容器高度计算可见起止索引，只渲染可视区域 + 少量 buffer 的 DOM 节点，上下用 padding 或占位元素撑开总高度，使滚动条行为与全量渲染一致。</p><h3 id="_7-如何避免首屏白屏" tabindex="-1">7. 如何避免首屏白屏？ <a class="header-anchor" href="#_7-如何避免首屏白屏" aria-label="Permalink to “7. 如何避免首屏白屏？”">​</a></h3><p>骨架屏、关键样式内联、SSR/SSG、资源 preload、减小首屏 JS、服务端直出 HTML。</p><hr><blockquote><p>更详细的代码示例与实践方案见 <a href="/page__blog-doc/面试题/优化/优化实践">优化实践</a>。</p></blockquote>`,82)])])}const u=l(r,[["render",s]]);export{g as __pageData,u as default};
